import java.util.Arrays;

final class MatrixUtils {
    private MatrixUtils() {
    }

    static int[][] copyOf(int[][] matrix) {
        MatrixValidator.requireRectangular(matrix, "Matrix");
        return copyRows(matrix);
    }

    static int[][] copyRows(int[][] matrix) {
        if (matrix == null) {
            throw new IllegalArgumentException("Matrix must not be null.");
        }

        int[][] copy = new int[matrix.length][];
        for (int rowIndex = 0; rowIndex < matrix.length; rowIndex++) {
            int[] row = matrix[rowIndex];
            copy[rowIndex] = row == null ? null : Arrays.copyOf(row, row.length);
        }

        return copy;
    }
}

public final class FloydWarshall {
    public static final int NO_PATH = Integer.MAX_VALUE;
    public static final int INF = NO_PATH;
    private static final String OVERFLOW_MESSAGE = "Path distance overflowed int range.";

    private FloydWarshall() {
    }

    public static int[][] shortestPaths(int[][] graph) {
        int vertexCount = MatrixValidator.requireSquare(graph, "Graph matrix");
        int[][] distances = MatrixUtils.copyOf(graph);

        for (int via = 0; via < vertexCount; via++) {
            relaxPathsVia(distances, via);
        }

        return distances;
    }

    public static boolean hasNegativeCycle(int[][] distances) {
        MatrixValidator.requireSquare(distances, "Distance matrix");

        for (int index = 0; index < distances.length; index++) {
            if (hasNegativeSelfDistance(distances, index)) {
                return true;
            }
        }

        return false;
    }

    public static boolean isReachable(int distance) {
        return distance != NO_PATH;
    }

    private static void relaxPathsVia(int[][] distances, int via) {
        int[] viaRow = distances[via];
        for (int[] fromRow : distances) {
            relaxRow(fromRow, viaRow, via);
        }
    }

    private static void relaxRow(int[] fromRow, int[] viaRow, int via) {
        int distanceToVia = fromRow[via];
        if (!isReachable(distanceToVia)) {
            return;
        }

        for (int to = 0; to < fromRow.length; to++) {
            relaxDistance(fromRow, viaRow, distanceToVia, to);
        }
    }

    private static void relaxDistance(int[] fromRow, int[] viaRow, int distanceToVia, int to) {
        int distanceFromVia = viaRow[to];
        if (!isReachable(distanceFromVia)) {
            return;
        }

        int candidateDistance = addDistances(distanceToVia, distanceFromVia);
        if (candidateDistance < fromRow[to]) {
            fromRow[to] = candidateDistance;
        }
    }

    private static boolean hasNegativeSelfDistance(int[][] distances, int vertex) {
        return distances[vertex][vertex] < 0;
    }

    private static int addDistances(int left, int right) {
        try {
            return Math.addExact(left, right);
        } catch (ArithmeticException exception) {
            throw new ArithmeticException(OVERFLOW_MESSAGE);
        }
    }
}

public final class DistanceMatrixFormatter {
    private static final String LINE_SEPARATOR = System.lineSeparator();

    private DistanceMatrixFormatter() {
    }

    public static String format(int[][] distances) {
        MatrixValidator.requireRectangular(distances, "Distance matrix");

        StringBuilder output = new StringBuilder();
        for (int[] row : distances) {
            output.append(formatRow(row)).append(LINE_SEPARATOR);
        }
        return output.toString();
    }

    private static String formatRow(int[] row) {
        StringBuilder output = new StringBuilder();

        for (int index = 0; index < row.length; index++) {
            if (index > 0) {
                output.append(' ');
            }
            output.append(formatDistance(row[index]));
        }

        return output.toString();
    }

    private static String formatDistance(int distance) {
        return FloydWarshall.isReachable(distance) ? Integer.toString(distance) : "INF";
    }
}

public final class FloydWarshallTest {
    private static final String LINE_SEPARATOR = System.lineSeparator();

    private FloydWarshallTest() {
    }

    public static void main(String[] args) {
        computesShortestPaths();
        doesNotMutateInput();
        detectsNegativeCycles();
        rejectsInvalidMatrices();
        rejectsInvalidFormatterMatrices();
        throwsOnDistanceOverflow();
        formatsUnreachableDistances();

        System.out.println("All FloydWarshall tests passed.");
    }

    private static void computesShortestPaths() {
        TestAssertions.assertMatrixEquals(
            ExampleGraphs.weightedDirectedGraphShortestPaths(),
            FloydWarshall.shortestPaths(ExampleGraphs.weightedDirectedGraph())
        );
    }

    private static void doesNotMutateInput() {
        int[][] graph = TestGraphs.acyclicThreeNodeGraph();

        int[][] original = MatrixUtils.copyOf(graph);
        FloydWarshall.shortestPaths(graph);

        TestAssertions.assertMatrixEquals(original, graph);
    }

    private static void detectsNegativeCycles() {
        int[][] graph = TestGraphs.negativeCycleGraph();

        int[][] distances = FloydWarshall.shortestPaths(graph);
        TestAssertions.assertTrue(FloydWarshall.hasNegativeCycle(distances), "Expected a negative cycle.");
    }

    private static void rejectsInvalidMatrices() {
        assertInvalidGraphRejected(null);
        assertInvalidGraphRejected(TestGraphs.invalidRectangularMatrix());
        assertInvalidGraphRejected(TestGraphs.matrixWithNullRow());
        assertInvalidGraphRejected(TestGraphs.nonSquareRowMatrix());
    }

    private static void rejectsInvalidFormatterMatrices() {
        assertInvalidDistanceMatrixRejected(null);
        assertInvalidDistanceMatrixRejected(TestGraphs.invalidRectangularMatrix());
    }

    private static void throwsOnDistanceOverflow() {
        int[][] graph = TestGraphs.overflowGraph();

        TestAssertions.assertThrows(ArithmeticException.class, () -> FloydWarshall.shortestPaths(graph));
    }

    private static void formatsUnreachableDistances() {
        int[][] distances = TestGraphs.unreachableTwoNodeDistances();

        String expected = "0 INF" + LINE_SEPARATOR + "INF 0" + LINE_SEPARATOR;
        TestAssertions.assertEquals(expected, DistanceMatrixFormatter.format(distances));
    }

    private static void assertInvalidGraphRejected(int[][] graph) {
        TestAssertions.assertThrows(IllegalArgumentException.class, () -> FloydWarshall.shortestPaths(graph));
    }

    private static void assertInvalidDistanceMatrixRejected(int[][] distances) {
        TestAssertions.assertThrows(IllegalArgumentException.class, () -> DistanceMatrixFormatter.format(distances));
    }
}

import java.util.Arrays;

final class TestAssertions {
    private TestAssertions() {
    }

    static void assertMatrixEquals(int[][] expected, int[][] actual) {
        if (!Arrays.deepEquals(expected, actual)) {
            throw new AssertionError(
                "Expected " + Arrays.deepToString(expected) + " but was " + Arrays.deepToString(actual)
            );
        }
    }

    static void assertTrue(boolean condition, String message) {
        if (!condition) {
            throw new AssertionError(message);
        }
    }

    static void assertEquals(String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError("Expected \"" + expected + "\" but was \"" + actual + "\"");
        }
    }

    static void assertThrows(Class<? extends Throwable> expectedType, Runnable action) {
        try {
            action.run();
        } catch (Throwable error) {
            if (expectedType.isInstance(error)) {
                return;
            }
            throw new AssertionError(
                "Expected " + expectedType.getSimpleName() + " but caught " + error.getClass().getSimpleName(),
                error
            );
        }

        throw new AssertionError("Expected " + expectedType.getSimpleName() + " to be thrown.");
    }
}
